DECLARATIONS.update({'_map_tick_word_comparison': {'signature': 'frame: MapTickFrame, left: Word, right: Word', 'returns': 'MapTickFrame', 'flow': 'difference = u16(left - right)\nreturn replace(frame, carry=left < right, zero=difference == 0, negative=bool(difference & 32768), overflow=bool((left ^ right) & (left ^ difference) & 32768))'}, 'advance_campaign_world_tick': {'signature': 'state: SceneState, frame: MapTickFrame', 'returns': 'MapTickFrame', 'flow': "checked_tick_frame(frame, state)\nframe = _call_world_tick_entry(state, 18576, frame)\nframe = _call_world_tick_entry(state, 18840, frame)\nvalue = replace_word(frame.motion_x, _word(state, 62982))\nvalue = replace_byte(value, u8(low8(value) | 64))\nstate.write(12582916, 2, low16(value))\nframe = replace(frame, motion_x=value, carry=False, zero=low16(value) == 0, negative=bool(low16(value) & 32768), overflow=False)\nframe = _call_world_tick_entry(state, 41840, frame)\nvalue = replace_word(frame.motion_x, _word(state, 62994))\nvalue = replace_word(value, low16(value) & 255)\nvalue = replace_word(value, u16(low16(value) << 1))\noffset = data_view(state, 'data_000f78').word(low16(value))\nframe = replace(frame, motion_x=replace_word(value, offset), source=state.table_at(3992), carry=False, zero=offset == 0, negative=bool(offset & 32768), overflow=False)\ntarget = u32(3992 + s16(offset))\nframe = _call_world_tick_entry(state, target, frame)\nmode = _word(state, 63172)\nframe = replace(frame, carry=False, zero=mode == 0, negative=bool(mode & 32768), overflow=False)\nif mode != 0:\n    return frame\nscene = _word(state, 62994)\nframe = _map_tick_word_comparison(frame, scene, 512)\nif scene == 512:\n    shade = _word(state, 62290)\n    frame = _map_tick_word_comparison(frame, shade, 16)\n    if frame.carry:\n        return frame\nframe = _call_world_tick_entry(state, 89574, frame)\nframe = _call_world_tick_entry(state, 92586, frame)\nreturn _call_world_tick_entry(state, 424444, frame)"}})

