DECLARATIONS.update({'_campaign_memory_logic_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, mask: int, operation: str, size: int=2', 'returns': 'FirstDeploymentFrame', 'flow': "value = state.read(address, size)\nif operation == 'and':\n    value &= mask\nelif operation == 'or':\n    value |= mask\nelif operation == 'xor':\n    value ^= mask\nelse:\n    raise ValueError('original campaign AND/OR/XOR role required')\nreturn _city_ui_store_fields(state, frame, address, value, size)"}})

DECLARATIONS.update({'_campaign_carry_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, carry: bool', 'returns': 'FirstDeploymentFrame', 'flow': 'status = frame.status | 1 if carry else frame.status & 30\nstate.sr = state.sr & 65504 | status\nreturn first_replace(frame, status=status)'}})

