DECLARATIONS.update({'advance_campaign_entry_fade_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 5188)\nframe = _movement_compare(state, frame, state.read(4294964050, 2), 16, 16)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964000, 2), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 1, 16)\n    if not frame.status & 4:\n        return frame\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964050, 2), 16)\n    frame = _movement_move(state, frame, 'target_y', 64, 16)\n    frame = first_replace(frame, roster=state.table_at(4294966144).cursor())\n    frame = _campaign_call_fields(state, frame, 56998, 5228)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964050, 1)\n    return _campaign_call_fields(state, frame, 41946, 5238)\nif frame.status & 4:\n    frame = _city_ui_store_fields(state, frame, 4294964736, 32)\n    return _city_ui_memory_arithmetic_fields(state, frame, 4294964050, 1)\nframe = _movement_compare(state, frame, state.read(4294964058, 2), 7, 16)\nif frame.status & 1:\n    return _campaign_call_fields(state, frame, 43300, 5276)\nframe = _movement_compare(state, frame, state.read(4294964050, 2), 33, 16)\nif not frame.status & 1:\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964754, 1)\n    return _city_ui_store_fields(state, frame, 4294964744, 2)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964000, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', 32, 16)\nframe = _city_ui_arithmetic_fields(state, frame, 'target_x', state.read(4294964050, 2), True)\nframe = _movement_move(state, frame, 'target_y', 64, 16)\nframe = first_replace(frame, roster=state.table_at(4294966144).cursor())\nframe = _campaign_call_fields(state, frame, 56998, 5324)\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294964050, 1)"}})

DECLARATIONS.update({'process_campaign_location_choice_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 5344)\nframe = _campaign_call_fields(state, frame, 43840, 5350)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964739, 1), 4)\nif not frame.status & 4:\n    frame = _city_ui_store_fields(state, frame, 4294964754, 512)\n    frame = _city_ui_store_fields(state, frame, 4294964050, 0, 2, True)\nelse:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964060, 2), 16)\n    frame = _city_ui_bit_fields(state, frame, state.read(4294964739, 1), 5)\n    pressed = not bool(frame.status & 4)\n    if not pressed:\n        frame = _city_ui_bit_fields(state, frame, state.read(4294964739, 1), 6)\n        pressed = not bool(frame.status & 4)\n    if not pressed:\n        frame = _campaign_call_fields(state, frame, 42288, 5390)\n    else:\n        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)\n        if not frame.status & 4:\n            frame = _campaign_call_fields(state, frame, 5498, 5420)\n            frame = _movement_move(state, frame, 'target_x', 172, 16)\n            frame = _campaign_call_fields(state, frame, 32906, 5432)\n        else:\n            frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964048, 1)\n            frame = _campaign_memory_logic_fields(state, frame, 4294964048, 3, 'and')\n            frame = _campaign_call_fields(state, frame, 42848, 5452)\n            frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964754, 1)\n            frame = _city_ui_store_fields(state, frame, 4294964058, 0, 2, True)\nreturn _campaign_call_fields(state, frame, 41946, 5496)"}})

DECLARATIONS.update({'select_campaign_location_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 5498)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964060, 2), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), 8, 16)\nif not frame.status & 1:\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_x', 1, True)\n    frame = _movement_compare(state, frame, state.read(4294964056, 2), 29, 16)\n    if not frame.status & 1:\n        frame = _city_ui_arithmetic_fields(state, frame, 'target_x', 1, True)\nframe = _city_ui_arithmetic_fields(state, frame, 'target_x', state.read(4294964056, 2))\nframe = _city_ui_shift_fields(state, frame, 'target_x', 2)\nframe = first_replace(frame, roster=state.table_at(871106).cursor())\nframe = _city_ui_store_fields(state, frame, 4294964064, frame.roster.word(low16(frame.target_x)))\nframe = _city_ui_store_fields(state, frame, 4294964062, frame.roster.word(low16(frame.target_x), 2))\nframe = _campaign_call_fields(state, frame, 5566, 5552)\nframe = _city_ui_store_fields(state, frame, 4294964754, 512)\nreturn _city_ui_store_fields(state, frame, 4294964050, 0, 2, True)"}})

DECLARATIONS.update({'clamp_campaign_camera_targets_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 5566)\nfor source, margin, limit, destination in ((4294964062, 112, 928, 4294964054), (4294964064, 160, 832, 4294964052)):\n    frame = _movement_move(state, frame, 'target_x', state.read(source, 2), 16)\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_x', margin, True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'target_x', 0, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_x), limit, 16)\n    if not frame.status & 5:\n        frame = _movement_move(state, frame, 'target_x', limit, 16)\n    frame = _city_ui_store_fields(state, frame, destination, low16(frame.target_x))\nreturn frame"}})

DECLARATIONS.update({'wait_for_campaign_location_confirmation_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _city_ui_frame_fields(state, frame, 5628)\nframe = _movement_compare(state, frame, state.read(4294964058, 2), 7, 16)\nif frame.status & 1:\n    frame = _campaign_call_fields(state, frame, 43300, 5644)\nelse:\n    frame = _city_ui_store_fields(state, frame, 4294964754, 514)\nreturn _campaign_call_fields(state, frame, 41946, 5660)'}})

DECLARATIONS.update({'process_campaign_camera_transition_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _city_ui_frame_fields(state, frame, 5662)\nfor target, token in ((40542, 5668), (41294, 5674), (4932, 5678), (5812, 5682)):\n    frame = _campaign_call_fields(state, frame, target, token)\nframe = _movement_test(state, frame, low16(frame.target_x), 16)\ncomplete = bool(frame.status & 4)\nif complete:\n    frame = _movement_test(state, frame, state.read(4294964002, 2), 16)\n    complete = bool(frame.status & 4)\nif complete:\n    frame = _movement_test(state, frame, state.read(16726328, 2), 16)\n    if frame.status & 4:\n        frame = _campaign_reset_selection_fields(state, frame)\n        frame = _city_ui_store_fields(state, frame, 4294964078, 0, 2, True)\n    else:\n        frame = _movement_compare(state, frame, state.read(4294964076, 2), 2, 16)\n        if frame.status & 4:\n            frame = _city_ui_store_fields(state, frame, 4294964754, 520)\n            frame = _city_ui_store_fields(state, frame, 4294964066, 4)\n        else:\n            frame = _city_ui_store_fields(state, frame, 4294964754, 518)\n            frame = _city_ui_store_fields(state, frame, 4294964066, 19)\n            frame = _city_ui_store_fields(state, frame, 4294964736, 232)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964133, 1), 0)\nif frame.status & 4:\n    frame = _city_ui_bit_fields(state, frame, state.read(4294964739, 1), 4)\n    if not frame.status & 4:\n        frame = _city_ui_store_fields(state, frame, 4294964754, 513)\nreturn _campaign_call_fields(state, frame, 41946, 5810)'}})

DECLARATIONS.update({'scroll_campaign_camera_toward_pointer_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 5812)\nframe = _movement_move(state, frame, 'target_x', 0, 16)\nfor name, source, margin, limit, camera, step, extent, target, negative_token, positive_token in (('target_y', 4294964062, 112, 928, 4294963988, 3, 224, 41164, 5880, 5922), ('unit', 4294964064, 160, 832, 4294963992, 4, 320, 41228, 5992, 6034)):\n    frame = _movement_move(state, frame, name, state.read(source, 2), 16)\n    frame = _city_ui_arithmetic_fields(state, frame, name, margin, True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, name, 0, 16)\n    frame = _movement_compare(state, frame, low16(getattr(frame, name)), limit, 16)\n    if not frame.status & 5:\n        frame = _movement_move(state, frame, name, limit, 16)\n    desired = low16(getattr(frame, name))\n    frame = _movement_compare(state, frame, desired, state.read(camera, 2), 16)\n    if frame.status & 4:\n        continue\n    increasing = not bool(frame.status & 5)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, camera, step, not increasing)\n    frame = _movement_compare(state, frame, desired, state.read(camera, 2), 16)\n    overshot = bool(frame.status & 1) if increasing else not (bool(frame.status & 4) or bool(frame.status & 8) != bool(frame.status & 2))\n    if overshot:\n        frame = _city_ui_store_fields(state, frame, camera, desired)\n    frame = first_replace(frame, scratch=state.table_at(u32(s16(state.read(camera, 2)))).cursor())\n    if increasing:\n        frame = first_replace(frame, scratch=frame.scratch.advance(extent))\n    frame = _campaign_call_fields(state, frame, target, positive_token if increasing else negative_token)\n    frame = _movement_move(state, frame, 'target_x', 1, 16)\nreturn frame"}})

DECLARATIONS.update({'_campaign_indexed_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, phase_address: int, table: int, code_base: int, continuation: int', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_move(state, frame, 'target_x', state.read(phase_address, 2), 16)\nframe = _city_ui_shift_fields(state, frame, 'target_x', 1)\nframe = _movement_move(state, frame, 'target_x', state.read(u32(table + s16(low16(frame.target_x))), 2), 16)\nreturn _campaign_call_fields(state, frame, u32(code_base + s16(low16(frame.target_x))), continuation)"}})

DECLARATIONS.update({'dispatch_campaign_selection_phase_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _city_ui_frame_fields(state, frame, 6040)\nframe = _campaign_call_fields(state, frame, 55532, 6046)\nframe = _campaign_call_fields(state, frame, 4932, 6050)\nframe = _campaign_indexed_phase_fields(state, frame, 4294964066, 6098, 6138, 6064)\nframe = _campaign_call_fields(state, frame, 41946, 6070)\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 6, 16)\nif frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294964754, 2), 523, 16)\n    if frame.status & 4:\n        return frame\nreturn _campaign_call_fields(state, frame, 41304, 6096)'}})

