DECLARATIONS.update({'prepare_campaign_selection_mode_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _city_ui_frame_fields(state, frame, 6150)\nframe = _movement_compare(state, frame, state.read(4294964076, 2), 2, 16)\neligible = False\nif not frame.status & 1:\n    for value in (2, 4, 5, 16):\n        frame = _movement_compare(state, frame, state.read(4294964826, 2), value, 16)\n        if frame.status & 4:\n            eligible = True\n            break\nif not eligible:\n    return _city_ui_memory_arithmetic_fields(state, frame, 4294964066, 1)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964132, 1), 3)\nif frame.status & 4:\n    frame = _city_ui_store_fields(state, frame, 4294964736, 112)\n    return _campaign_call_fields(state, frame, 90732, 6222)\nframe = _city_ui_store_fields(state, frame, 4294964066, 8)\nframe = _city_ui_store_fields(state, frame, 4294964074, 0, 2, True)\nframe = _city_ui_store_fields(state, frame, 4294964078, 0, 2, True)\nframe = _movement_compare(state, frame, state.read(4294964108, 2), 161, 16)\nif not frame.status & 4:\n    frame = _campaign_call_fields(state, frame, 83316, 6256)\nframe = _movement_compare(state, frame, state.read(4294964826, 2), 5, 16)\nif frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294964602, 2), 164, 16)\n    if frame.status & 4:\n        return _campaign_call_fields(state, frame, 73276, 6282)\n    return _campaign_call_fields(state, frame, 72946, 6292)\nreturn frame'}})

