DECLARATIONS.update({'initialize_campaign_selection_mode_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 6308)\nframe = _movement_compare(state, frame, state.read(4294964076, 2), 2, 16)\nshow_status = False\nif not frame.status & 1:\n    frame = _movement_compare(state, frame, state.read(4294964826, 2), 4, 16)\n    show_status = bool(frame.status & 4)\n    if not show_status:\n        frame = _movement_compare(state, frame, state.read(4294964076, 2), 3, 16)\n        if frame.status & 4:\n            frame = _movement_compare(state, frame, state.read(4294964826, 2), 18, 16)\n            if not frame.status & 1:\n                frame = _movement_compare(state, frame, state.read(4294964826, 2), 20, 16)\n                show_status = bool(frame.status & 5)\nif show_status:\n    frame = _city_ui_store_fields(state, frame, 4294964736, 112)\n    frame = _campaign_call_fields(state, frame, 90732, 6370)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964108, 2), 129, 16)\n    if not frame.status & 4:\n        frame = _campaign_call_fields(state, frame, 22164, 6390)\n    frame = _campaign_call_fields(state, frame, 23228, 6396)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964133, 1), 0)\nif frame.status & 4:\n    frame = _movement_test(state, frame, state.read(4294964076, 2), 16)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964066, 1)\n    frame = _city_ui_store_fields(state, frame, 4294964074, 0, 2, True)\nelse:\n    frame = _city_ui_store_fields(state, frame, 4294964066, 8)\n    frame = _city_ui_store_fields(state, frame, 4294964074, 0, 2, True)\n    frame = _city_ui_store_fields(state, frame, 4294964078, 0, 2, True)\n    frame = _movement_compare(state, frame, state.read(4294964096, 2), 122, 16)\n    if frame.status & 4:\n        frame = _city_ui_store_fields(state, frame, 4294964736, 76)\n    else:\n        frame = _movement_compare(state, frame, state.read(4294964096, 2), 102, 16)\n        if frame.status & 4:\n            frame = _city_ui_store_fields(state, frame, 4294964736, 56)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964133, 1), 0)\nif not frame.status & 4:\n    return frame\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _campaign_call_fields(state, frame, 24392, 6496)\nframe = _city_ui_store_fields(state, frame, 4294964790, low16(frame.count))\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _city_ui_shift_fields(state, frame, 'target_x', 2)\nframe = first_replace(frame, roster=state.table_at(4294960220).cursor())\nreturn _city_ui_store_fields(state, frame, u32(frame.roster.base + s16(low16(frame.target_x)) + 2), low16(frame.count))"}})

DECLARATIONS.update({'_campaign_parallel_packet_word_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, displacement: int, parallel: int, primary: int, parallel_clear: bool=False, primary_clear: bool=False', 'returns': 'FirstDeploymentFrame', 'flow': 'frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + displacement), parallel, 2, parallel_clear)\nframe = _city_ui_store_fields(state, frame, frame.roster.base, primary, 2, primary_clear)\nreturn first_replace(frame, roster=frame.roster.advance(2))'}})

DECLARATIONS.update({'_campaign_frame_border_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, confirmation: bool', 'returns': 'FirstDeploymentFrame', 'flow': "frame = first_replace(frame, roster=state.table_at(4294955264).cursor())\nframe = first_replace(frame, roster=frame.roster.advance(s16(state.read(4294963994, 2))))\nframe = _campaign_parallel_packet_word_fields(state, frame, 30, 13, 13)\nframe = _campaign_parallel_packet_word_fields(state, frame, 30, 49460, 49332)\nif confirmation:\n    frame = _campaign_parallel_packet_word_fields(state, frame, 30, 0, 0, True, True)\nframe = _campaign_parallel_packet_word_fields(state, frame, 30, 50050, 50048)\nframe = _movement_move(state, frame, 'target_x', 7 if confirmation else 10, 16)\nwhile True:\n    frame = _campaign_parallel_packet_word_fields(state, frame, 30, 49153, 50049)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _campaign_parallel_packet_word_fields(state, frame, 30, 52098, 52096)\nif confirmation:\n    for _ in range(2):\n        frame = _campaign_parallel_packet_word_fields(state, frame, 30, 0, 0, True, True)\nframe = _city_ui_store_fields(state, frame, u32(frame.roster.base + 30), 0, 2, True)\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294963994, 60)"}})

