DECLARATIONS.update({'update_campaign_selection_delay_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 6604)\nowned = False\nfor value in (6, 15, 21):\n    frame = _movement_compare(state, frame, state.read(4294964108, 2), value, 16)\n    if frame.status & 4:\n        owned = True\n        break\nif not owned:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\n    frame = first_replace(frame, roster=state.table_at(4294964263).cursor())\n    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)\n    frame = _movement_compare(state, frame, low8(frame.target_x), state.read(4294964087, 1), 8)\n    owned = bool(frame.status & 4)\nif not owned:\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 1, 16)\n    if frame.status & 1:\n        return _campaign_call_fields(state, frame, 22496, 6756)\nelse:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964132, 2), 16)\n    frame = _city_ui_bit_fields(state, frame, frame.target_x, 14)\n    threshold = 5 if not frame.status & 4 else 7\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), threshold, 16)\n    if frame.status & 1:\n        return _campaign_call_fields(state, frame, 22496, 6756)\nframe = _campaign_call_fields(state, frame, 23168, 6714)\nframe = _movement_compare(state, frame, state.read(4294964074, 2), 5, 16)\nif frame.status & 1:\n    return _city_ui_store_fields(state, frame, 4294964066, 15)\nframe = _city_ui_memory_arithmetic_fields(state, frame, 4294964066, 1)\nframe = _city_ui_store_fields(state, frame, 4294964744, 6)\nframe = _campaign_memory_logic_fields(state, frame, 4294964132, 33792, 'or')\nreturn _campaign_memory_logic_fields(state, frame, 4294964132, 64959, 'and')"}})

DECLARATIONS.update({'process_campaign_selection_input_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 6768)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_x', low8(frame.target_x) & 3, 8)\npage_input = not bool(frame.status & 4)\nif page_input:\n    eligible = False\n    for value in (6, 15, 21):\n        frame = _movement_compare(state, frame, state.read(4294964108, 2), value, 16)\n        if frame.status & 4:\n            eligible = True\n            break\n    if not eligible:\n        frame = _movement_move(state, frame, 'target_y', state.read(4294964068, 2), 16)\n        frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 255, 16)\n        frame = first_replace(frame, roster=state.table_at(4294964263).cursor())\n        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_y)), 8)\n        frame = _movement_compare(state, frame, low8(frame.target_y), state.read(4294964087, 1), 8)\n        eligible = bool(frame.status & 4)\n    if eligible:\n        frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964744, 1, True)\n        if frame.status & 4:\n            frame = _city_ui_bit_fields(state, frame, frame.target_x, 1)\n            if frame.status & 4:\n                frame = _movement_test(state, frame, state.read(4294964072, 2), 16)\n                change = not bool(frame.status & 4)\n                if change:\n                    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964072, 1, True)\n            else:\n                frame = _movement_move(state, frame, 'choice', 6, 16)\n                frame = _city_ui_bit_fields(state, frame, state.read(4294964132, 1), 6)\n                if not frame.status & 4:\n                    frame = _movement_move(state, frame, 'choice', 8, 16)\n                frame = _movement_compare(state, frame, low16(frame.choice), state.read(4294964072, 2), 16)\n                change = not bool(frame.status & 5)\n                if change:\n                    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964072, 1)\n            if change:\n                frame = _city_ui_store_fields(state, frame, 4294964074, 0, 2, True)\n                frame = _city_ui_store_fields(state, frame, 4294964066, 5)\n            return _campaign_selection_commit_fields(state, frame)\n        return _campaign_selection_commit_fields(state, frame)\nframe = _movement_test(state, frame, state.read(4294964068, 2), 16)\nif frame.status & 8:\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964738, 2), 16)\n    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 47, 16)\n    if frame.status & 4:\n        frame = _city_ui_store_fields(state, frame, 4294964744, 6)\n        return _campaign_selection_commit_fields(state, frame)\nelse:\n    frame = _city_ui_store_fields(state, frame, 4294964744, 6)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964738, 1), 4)\nif not frame.status & 4:\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964066, 1)\n    return _city_ui_store_fields(state, frame, 4294964074, 13)\nreturn _campaign_selection_commit_fields(state, frame)"}})

DECLARATIONS.update({'_campaign_selection_commit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _movement_test(state, frame, state.read(4294964068, 2), 16)\nif frame.status & 8:\n    return frame\nframe = _city_ui_bit_fields(state, frame, state.read(4294964739, 1), 5)\nif frame.status & 4:\n    return frame\nspecial = False\nfor value in (6, 15, 21):\n    frame = _movement_compare(state, frame, state.read(4294964108, 2), value, 16)\n    if frame.status & 4:\n        special = True\n        break\nif special:\n    frame = _movement_test(state, frame, state.read(4294964782, 2), 16)\n    if frame.status & 8:\n        return _campaign_selection_guarded_commit_fields(state, frame)\nelse:\n    frame = _movement_test(state, frame, state.read(4294964076, 2), 16)\n    if not frame.status & 4:\n        return _campaign_selection_guarded_commit_fields(state, frame)\n    frame = _movement_test(state, frame, state.read(4294964782, 1), 8)\n    if frame.status & 8:\n        return frame\nframe = _movement_move(state, frame, 'target_x', 172, 16)\nframe = _campaign_call_fields(state, frame, 32906, 7056)\nframe = _city_ui_store_fields(state, frame, 4294964066, 8)\nfor address in (4294964074, 4294964824, 4294964078):\n    frame = _city_ui_store_fields(state, frame, address, 0, 2, True)\nframe = _city_ui_store_fields(state, frame, 4294964088, 1)\nreturn _city_ui_store_fields(state, frame, 4294964822, 0, 2, True)"}})

