DECLARATIONS.update({'request_affordable_action_panel_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_battle_ai.business_formation import _first_compare_long\nframe = _campaign_screen_enter_fields(state, frame, 1072)\nframe = first_replace(frame, candidates=state.table_at(4294955776).cursor())\nframe = _movement_move(state, frame, 'target_x', 31, 16)\nframe = _campaign_screen_fill_fields(state, frame, 'target_x', 286331153, 2080, True)\nframe = _campaign_screen_style_fields(state, frame)\nframe = _movement_move(state, frame, 'count', 2, 16)\nframe = first_replace(frame, roster=state.table_at(2264).cursor())\nframe = _campaign_call_fields(state, frame, 44682, 2114)\nframe = _campaign_emit_fields(state, frame, 2114, 12582916, 1342177280, 4)\nframe = first_replace(frame, roster=state.table_at(4294955776).cursor())\nframe = _movement_move(state, frame, 'target_x', 223, 16)\nframe = _campaign_screen_transfer_fields(state, frame, 'roster', 'target_x', 2132)\nframe = _campaign_screen_style_fields(state, frame)\nframe = _campaign_call_fields(state, frame, 20588, 2156)\nframe = _movement_compare(state, frame, state.read(4294964108, 2), 39, 16)\nif frame.status & 4:\n    frame = _campaign_call_fields(state, frame, 2278, 2168)\n    frame = _campaign_emit_fields(state, frame, 2168, 4294964126, frame.target_x, 4)\n    frame = _movement_move(state, frame, 'target_x', state.read(4294964136, 2), 16)\n    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)\n    frame = first_replace(frame, roster=state.table_at(4294959100).cursor())\n    frame = _movement_move_long(state, frame, 'target_x', frame.roster.long(low16(frame.target_x)))\n    frame = _first_compare_long(frame, frame.target_x, state.read(4294964126, 4))\n    state.sr = state.sr & 65504 | frame.status\n    if frame.status & 1:\n        frame = _campaign_emit_fields(state, frame, 2192, 4294964066, 2)\n        frame = _campaign_emit_fields(state, frame, 2198, 4294964066, 35)\n        frame = _campaign_emit_fields(state, frame, 2204, 4294964744, 120)\n        frame = _movement_move(state, frame, 'target_x', 189, 16)\n        frame = _campaign_call_fields(state, frame, 423666, 2220)\n        return _campaign_tail_fields(state, frame, 1548)\nframe = _movement_compare(state, frame, state.read(4294964108, 2), 177, 16)\nselected = bool(frame.status & 4)\nif not selected:\n    frame = _movement_compare(state, frame, state.read(4294964108, 2), 186, 16)\n    selected = bool(frame.status & 4)\nif selected:\n    frame = _campaign_call_fields(state, frame, 91608, 2250)\nframe = _campaign_emit_fields(state, frame, 2250, 4294964066, 18)\nreturn _campaign_call_fields(state, frame, 44872, 2262)"}})

